        {
            cl = -cl;
            cr = -cr;
        }
        if (cl >= target && cr >= target) break;

        diff = cl - cr;
        l = speed - diff / 8;
        r = speed + diff / 8;
        if (l > 100) l = 100;
        if (l < -100) l = -100;
        if (r > 100) r = 100;
        if (r < -100) r = -100;
        SetMotor(motorL, l);
        SetMotor(motorR, r);
    }
    SetMotor(motorL, 0);
    SetMotor(motorR, 0);
